local _, addon = ...

addon.localeData.frFR.texts = {
 HUNTERS_MARK={ziel={"Je vous ai à l'œil, %s.","*fixe %s avec le regard mesuré d'un chasseur.*"},gruppe={"La proie est marquée.","*désigne la cible marquée aux compagnons.*"}},
 ARCANE_SHOT={ziel={"Le feu arcanique vous trouvera, %s.","*tire sur %s tandis que l'énergie arcanique embrase le projectile.*"},gruppe={"Charge arcanique prête. Feu.","*décoche un tir nimbé de lumière arcanique.*"}},
 AIMED_SHOT={ziel={"Un souffle. Une cible. Un tir, %s.","*vise soigneusement %s et reste parfaitement immobile.*"},gruppe={"*retient son souffle et ajuste soigneusement sa visée.*","J'ai un angle. Ne bougez pas."}},
 MULTI_SHOT={ziel={"Une seule cible ne suffira pas aujourd'hui, %s.","*balaye %s et les cibles voisines de son arme.*"},gruppe={"*décoche plusieurs tirs en succession rapide.*","Plusieurs cibles. Maintenant."}},
 STEADY_SHOT={ziel={"Visée stable. Tir propre, %s.","*vise de nouveau %s et garde l'arme parfaitement stable.*"},gruppe={"Pas de hâte. Des tirs propres.","*expire lentement et vise de nouveau.*"}},
 KILL_COMMAND={ziel={"Maintenant ! Sur %s !","*adresse à son compagnon un signe sec vers %s.*"},gruppe={"Vas-y ! Maintenant !","*envoie son compagnon en avant d'un ordre bref.*"}},
 MEND_PET={ziel={"Doucement, vieil ami. Je m'en occupe.","*s'agenouille près de %s et soigne les blessures avec précaution.*"},gruppe={"Doucement. Ça va aller.","*soigne les blessures de son compagnon avec des gestes sûrs.*"}},
 REVIVE_PET={ziel={"Reviens, vieil ami. La chasse n'est pas terminée.","*se penche vers %s et cherche anxieusement un signe de vie.*"},gruppe={"Allez. Je ne pars pas sans toi.","*s'agenouille près de son compagnon tombé et refuse de s'éloigner.*"}},
 FEED_PET={ziel={"Tiens. Tu l'as mérité.","*offre à %s une ration bien méritée.*"},gruppe={"Tu auras ta part. Comme toujours.","*regarde son compagnon manger avec satisfaction.*"}},
 TAMING={ziel={"Doucement, %s. Je ne vous veux aucun mal.","*abaisse son arme et tend lentement une main ouverte vers %s.*"},gruppe={"La confiance ne se force pas.","*s'approche lentement sans geste brusque.*"}},
 TRAP={ziel={"Regardez où vous mettez les pieds, %s. Trop tard.","*jette un regard vers le piège soigneusement dissimulé près de %s.*"},gruppe={"Il ne manque plus que quelqu'un pour marcher dedans.","*dissimule soigneusement un piège dans le terrain.*"}},
 FLARE={ziel={"Assez joué à cache-cache, %s.","*tire une fusée éclairante vers %s et baigne la zone de lumière.*"},gruppe={"Voyons qui se cache là.","*tire une fusée éclatante dans les ombres.*"}},
 ASPECT_HAWK={gruppe={"Les yeux ouverts. Le faucon voit le premier.","*se redresse, le regard soudain vif et attentif.*"}}, ASPECT_CHEETAH={gruppe={"Suivez si vous pouvez.","*se penche en avant et accélère vivement.*"}}, ASPECT_MONKEY={gruppe={"Rester immobile serait mauvais pour la santé.","*relâche sa posture et commence à bouger de façon imprévisible.*"}}, RAPID_FIRE={gruppe={"Ne relâchez pas la pression !","*enchaîne les tirs à grande vitesse.*"}}, DISENGAGE={gruppe={"Voilà. La distance est rétablie.","*bondit en arrière pour recréer de l'espace.*"}}, MELEE={ziel={"Alors de près, %s.","*abaisse l'arme à distance et tire une arme de mêlée face à %s.*"},gruppe={"Alors à portée de bras.","*passe à une arme de mêlée.*"}}, RAPTOR_STRIKE={ziel={"Tu t'es trop approché, %s. Mauvais choix.","*transforme l'assaut de %s en une riposte au corps à corps.*","Un chasseur sait frapper de près, %s.","*tire son arme de mêlée et frappe vers %s.*"},gruppe={"Un bon chasseur sait quand réduire la distance.","*tire son arme de mêlée et prend appui.*","La chasse ne cesse pas quand les flèches ne servent plus.","*porte un coup précis après avoir avancé d'un pas.*"}}, TRACKING={ziel={"La piste est fraîche, %s.","*s'accroupit et étudie les traces laissées par %s.*"},gruppe={"Là. La piste est claire.","*examine le sol, les branches et le vent à la recherche de signes récents.*"}}, CAMOUFLAGE={gruppe={"Ne pas bouger. Ne pas se faire remarquer. Disparaître.","*se fond dans le couvert et le terrain environnant.*"}}, VICTORY={ziel={"La chasse est terminée, %s.","*abaisse son arme après le dernier coup et observe %s en silence.*"},gruppe={"La piste s'arrête ici.","*vérifie les alentours avant d'abaisser son arme.*"}},
    -- Nouvelles actions du chasseur dans WoW Forever
    TAME_BEAST = { gruppe = { "La confiance se gagne, elle ne s'attache pas à une laisse.", "Une main ouverte vaut mieux qu'une arme levée.", "*s'agenouille en gardant une distance respectueuse.*", "*reste immobile jusqu'à ce que l'animal s'approche de lui-même.*" }, ziel = { "Je ne veux pas te briser, %s. Je veux te comprendre." }, },
    CALL_PET = { gruppe = { "Viens, vieux compagnon. D'abord le travail, ensuite le repas.", "Un seul sifflement peut contenir toute une amitié.", "*lance un sifflement bref et familier.*", "*cherche une silhouette connue entre les arbres.*" }, },
    DISMISS_PET = { gruppe = { "Repose-toi, mon ami. Je monte la garde.", "Même le chasseur fidèle mérite un coin tranquille.", "*caresse le cou de l'animal et lui fait un signe doux.*", "*attend que son compagnon disparaisse en sécurité.*" }, ziel = { "À plus tard, %s. Garde-moi quelques provisions." }, },
    EAGLE_EYE = { gruppe = { "Mes yeux voyagent plus loin que mes bottes.", "Comprendre le terrain avant de choisir la route.", "*abrite ses yeux d'une main et scrute l'horizon.*", "*suit du regard un mouvement très lointain.*" }, },
    EYES_OF_THE_BEAST = { gruppe = { "Deux paires d'yeux, un seul dessein, et une bien meilleure ouïe.", "Le monde sent tout autrement à hauteur de quatre pattes.", "*se tait pour se concentrer sur les sens de son compagnon.*", "*tourne la tête vers un son imperceptible aux autres.*" }, ziel = { "Montre-moi ce que tu vois, %s." }, },
    SCARE_BEAST = { gruppe = { "Même les plus longs crocs connaissent la peur.", "Un cri suffira peut-être à éviter un long combat.", "*se redresse et pousse un cri d'avertissement aigu.*", "*campe fermement sur ses jambes sans céder un pas.*" }, ziel = { "Recule, %s. Toutes les proies ne se laissent pas mordre." }, },
    BEAST_LORE = { gruppe = { "Crocs, pelage et démarche racontent toute une histoire.", "Observer est un art. Survivre en est un autre.", "*étudie la posture de la bête et ses oreilles.*", "*note discrètement ses traces et ses habitudes.*" }, ziel = { "Magnifique créature, %s. Et pleine de secrets." }, },
    SUMMON_HAWK = { gruppe = { "Le ciel est assez vaste pour deux chasseurs.", "Quand un ami possède des ailes, la piste paraît plus courte.", "*lève le bras pour accueillir un rapace qui tournoie.*", "*suit une ombre au-dessus de la cime des arbres.*" }, },
    ASPECT_BEAST = { gruppe = { "Aujourd'hui, mes pas n'ont aucune raison de s'entendre.", "Pour comprendre la nature, il faut un instant s'y fondre.", "*avance d'un pas souple et presque silencieux.*", "*éprouve le vent avant de baisser sa silhouette.*" }, },
    ASPECT_PACK = { gruppe = { "Ensemble, nous allons plus vite. Ensemble, nous rentrerons.", "Une bonne route est plus courte au même rythme.", "*fait signe à ses compagnons d'avancer ensemble.*", "*adapte son allure pour garder le groupe uni.*" }, },
    ASPECT_WILD = { gruppe = { "Le vent apporte plus que le froid à qui sait l'écouter.", "Les fourrés cachent des dangers que l'acier n'arrête pas.", "*effleure de la mousse et des feuilles du bout des doigts.*", "*respire lentement l'odeur humide de la forêt.*" }, },
    TRANQUILIZING_SHOT = { gruppe = { "Un ennemi furieux réfléchit mieux lorsque sa rage s'apaise.", "Parfois, le meilleur tir est celui qui calme.", "*vérifie une munition spéciale et stabilise son arme.*", "*prend le temps de viser pour mettre fin à la frénésie.*" }, ziel = { "Assez de rage, %s. Il est temps de réfléchir." }, },
    INTIMIDATION = { gruppe = { "Mon compagnon n'est pas aussi impressionné que tu le crois.", "Un grondement explique parfois mieux qu'un sermon.", "*fait un signe bref à son compagnon pour avancer.*", "*s'écarte afin de laisser la voie libre à la bête.*" }, ziel = { "Regarde mon ami dans les yeux, %s, et réfléchis." }, },
    BESTIAL_WRATH = { gruppe = { "Nous nous sommes trouvés. Maintenant, nous luttons ensemble.", "La fureur ne se dompte pas, mais elle trouve une direction.", "*pose brièvement une main sur le flanc de son compagnon.*", "*libère la bête d'un cri court et familier.*" }, ziel = { "Montre-leur ton courage, %s !" }, },
    AUTO_SHOT = { gruppe = { "Le bon tireur trouve son rythme.", "Tous les tirs n'ont pas besoin d'un discours. Certains exigent le silence.", "*reprend sa visée avec un geste parfaitement rodé.*", "*garde un souffle égal tout en suivant sa cible.*" }, ziel = { "Ne bouge pas, %s. Tu me facilites la tâche." }, },
    SERPENT_STING = { gruppe = { "Le serpent n'a pas besoin de mordre deux fois.", "La patience est la pointe la plus acérée du carquois.", "*examine une pointe soigneusement empoisonnée.*", "*glisse une munition préparée dans son arme.*" }, ziel = { "La nature t'envoie un cadeau, %s. Il prend son temps." }, },
    CONCUSSIVE_SHOT = { gruppe = { "La hâte ne remplace pas une voie de fuite.", "Un poursuivant qui trébuche ne rattrape personne.", "*vise la trajectoire de course plutôt que le torse.*", "*tire rapidement et observe les appuis de l'adversaire.*" }, ziel = { "Pas si vite, %s. Nous avons encore à parler." }, },
    DISTRACTING_SHOT = { gruppe = { "Par ici ! Si tu cherches des ennuis, regarde-moi.", "Une bataille change lorsque quelqu'un ose se montrer.", "*sort de sa cachette et tire pour se faire remarquer.*", "*attire l'attention d'un geste volontaire.*" }, ziel = { "Me voici, %s. C'est à moi qu'il faut parler." }, },
    SCORPID_STING = { gruppe = { "Le scorpion ne demande jamais la taille de sa proie.", "Une petite piqûre peut voler la force d'un géant.", "*choisit une pointe exceptionnellement fine.*", "*guette les premiers signes de faiblesse.*" }, ziel = { "La force seule ne te sauvera pas, %s." }, },
    TRUESHOT_AURA = { gruppe = { "Souffle égal, ligne claire, un instant partagé.", "Nous visons séparément, mais restons unis.", "*fait signe aux tireurs et vérifie leurs positions.*", "*s'installe dans une posture de tir précise et stable.*" }, },
    VIPER_STING = { gruppe = { "Certains sorts se tarissent avant leur dernier mot.", "La vipère cherche la puissance, pas le sang.", "*inspecte une pointe brillant d'une lueur pâle.*", "*observe attentivement les mains du lanceur de sorts.*" }, ziel = { "Ta puissance s'épuise, %s. Tu le sens ?" }, },
    SNIPER_SHOT = { gruppe = { "Un souffle. Une décision. Une très longue distance.", "Plus le tir est lointain, plus il faut regarder de près.", "*ralentit sa respiration et ajuste son arme avec précision.*", "*reste parfaitement immobile en attendant le moment juste.*" }, ziel = { "Inutile de me chercher, %s. Il est déjà trop tard." }, },
    VOLLEY = { gruppe = { "Le ciel va devenir franchement désagréable.", "Je déconseille de rester là où la pluie va tomber.", "*désigne une zone au sol et lève son arme à distance.*", "*envoie une succession de projectiles sur le champ de bataille.*" }, },
    SCATTER_SHOT = { gruppe = { "Une seconde de confusion suffit amplement.", "Certains tirs ne blessent pas, ils achètent du temps.", "*pivote brusquement et tire à très courte portée.*", "*profite de l'instant de surprise pour changer de position.*" }, ziel = { "Prends un instant pour retrouver ton chemin, %s !" }, },
    TRACK_BEASTS = { gruppe = { "Une piste fraîche parle plus fort qu'un cor de chasse.", "Griffes, poils et terre remuée racontent toute l'histoire.", "*compare la distance entre plusieurs empreintes de pattes.*", "*s'agenouille près du sentier pour examiner une trace.*" }, },
    TRACK_HUMANOIDS = { gruppe = { "Les voyageurs à deux jambes laissent beaucoup de traces.", "Les semelles des bottes ont leurs propres histoires.", "*examine une branche cassée à hauteur d'épaule.*", "*lit le rythme irrégulier des pas dans la terre.*" }, },
    WING_CLIP = { gruppe = { "Pour me poursuivre, il te faudra de meilleures jambes.", "Une entaille bien placée arrête souvent la poursuite.", "*esquive une attaque et balaie bas avec son arme.*", "*fait un pas de côté pour couper la route de son poursuivant.*" }, ziel = { "Ralentis, %s. Nous n'avons pas fini." }, },
    IMMOLATION_TRAP = { gruppe = { "Une frontière invisible peut devenir très chaude.", "Celui qui croit tous les chemins sûrs ne l'apprend qu'une fois.", "*dissimule un piège brûlant sous la terre et les pierres.*", "*vérifie le déclencheur et recule prudemment.*" }, },
    MONGOOSE_BITE = { gruppe = { "Une bonne esquive est la moitié de la réponse.", "La mangouste attend l'erreur, pas l'invitation.", "*se glisse hors d'une attaque et riposte d'un coup rapide.*", "*efface une épaule et lance aussitôt sa lame en avant.*" }, ziel = { "Cet élan m'appartient désormais, %s." }, },
    TRACK_UNDEAD = { gruppe = { "Certaines traces ne sentent plus la vie.", "Les morts ne marchent guère en douceur.", "*examine une terre froide et étrangement silencieuse.*", "*retient son souffle en écoutant un bruit sans vie.*" }, },
    FREEZING_TRAP = { gruppe = { "Un peu de calme ne ferait de mal à aucune bataille.", "Cours trop vite et le sentier deviendra de glace.", "*cache un piège gelé sous une fine couche de terre.*", "*vérifie qu'aucun allié ne touchera le déclencheur.*" }, },
    TRACK_HIDDEN = { gruppe = { "Ce qui est invisible n'est pas toujours inaudible.", "Le vent trahit les endroits où il ne devrait pas souffler.", "*écoute le plus léger froissement hors de vue.*", "*scrute les ombres à la recherche d'un mouvement anormal.*" }, },
    COUNTERATTACK = { gruppe = { "Merci pour cette ouverture dans ta défense.", "Une attaque est parfois une invitation. Je l'accepte.", "*dévie un coup et ramène aussitôt son arme.*", "*laisse l'ennemi se découvrir avant une riposte précise.*" }, ziel = { "Ta chance est passée, %s. À mon tour." }, },
    TRACK_ELEMENTALS = { gruppe = { "Quand les éléments dansent, la terre s'en souvient.", "Cendre, givre et vent étrange montrent le chemin.", "*touche une pierre anormalement chaude.*", "*suit une traînée de givre et d'air crépitant.*" }, },
    FROST_TRAP = { gruppe = { "Tous les chemins ne mènent pas vite à destination.", "Un pas, un souffle de givre et la poursuite ralentit.", "*pose le déclencheur d'un piège glacé sous des feuilles.*", "*mémorise une voie sûre autour de l'engin caché.*" }, },
    FEIGN_DEATH = { gruppe = { "Faire le mort est un art. Ne pas rire en est un autre.", "Un chasseur avisé n'a pas besoin de gagner debout.", "*s'écroule avec une solennité exagérée.*", "*ne bouge pas même une paupière tant que le danger subsiste.*" }, },
    LACERATE = { gruppe = { "Une blessure n'est pas un discours, mais on la comprend.", "Approche et découvre le tranchant de mon acier.", "*entaille durement avant de retirer sa lame.*", "*adopte une position basse pour un coup de mêlée bref.*" }, ziel = { "Ce pas t'a coûté cher, %s." }, },
    TRACK_DEMONS = { gruppe = { "Soufre et silence font rarement bon ménage.", "Cette piste n'appartient à aucune bête ordinaire.", "*examine des signes brûlés dans la terre.*", "*observe une trace qui semble remonter le vent.*" }, },
    EXPLOSIVE_TRAP = { gruppe = { "Le feu répond parfois bien trop fort à une question.", "Ce chemin va soudain devenir plus court. Pour quelqu'un.", "*enfouit un déclencheur explosif et vérifie la distance.*", "*se place soigneusement derrière un rocher.*" }, },
    TRACK_GIANTS = { gruppe = { "Les grands pieds sont un camouflage déplorable.", "Quand les arbres sont brisés, inutile de chercher les petites traces.", "*pose la main au milieu d'une empreinte immense.*", "*suit du regard une rangée d'arbres déracinés.*" }, },
    TRACK_DRAGONKIN = { gruppe = { "Écailles, griffes, marques de brûlure. Ce n'est pas un cerf.", "Qui chasse les dragons doit prévoir sa retraite.", "*fait tourner une grande écaille entre ses doigts.*", "*suit prudemment une trace de brûlure sur la pierre.*" }, },
    DETERRENCE = { gruppe = { "Un pas en arrière n'est pas une capitulation.", "L'acier ne sert à rien sans un plan pour survivre.", "*adopte une garde serrée et solide.*", "*place ses armes pour ne laisser aucune ouverture facile.*" }, },
    STRIDER_KICK = { gruppe = { "Tu n'avais pas vu venir ma botte de cet angle.", "Les longues jambes savent donner des réponses courtes.", "*lance un coup de pied bas tout en changeant de direction.*", "*déplace son poids et projette son talon en avant.*" }, ziel = { "Un pas trop près, %s. Apprends la distance." }, },
    BEAST_TRAINING = { gruppe = { "La première leçon commence par la confiance, pas par un ordre.", "Un compagnon apprend plus vite quand on l'écoute aussi.", "*répète patiemment un signal et attend la réaction.*", "*récompense un exercice réussi d'un signe chaleureux.*" }, },
}
